!function(){"use strict";function subFamiliaCtrl($scope,subFamiliaSvc,commonSvc,tS){$scope.dataSearch={pageIndex:1,pageSize:10,maxSize:5},$scope.totalRecords=0,$scope.recordsQuantity=[5,10,25,50,100,200,500],$scope.getSubFamilias=function(){try{showLoader(),$scope.subFamilias=[],subFamiliaSvc.getAll($scope.dataSearch).then(response=>{$scope.subFamilias=response,$scope.totalRecords=$scope.subFamilias.length>0?$scope.subFamilias[0].totalRecords:0,hideLoader()}).catch(error=>{hideLoader(),console.log(error)})}catch(error){hideLoader(),console.log(error)}},$scope.getSubFamilias(),$scope.pagechanged=function(){$scope.getSubFamilias()},$scope.changePageSize=function(){$scope.dataSearch.pageIndex=1,$scope.getSubFamilias()},$scope.resultModal=function(item){$scope.getSubFamilias()},$scope.exportTableToExcel=()=>{try{showLoader();const subFamilias=$scope.subFamilias.map(item=>({codigo:item.codigo,descripcion:item.descripcion}));commonSvc.exportTableToExcel({arr:subFamilias,fileName:"SubFamilias"})}catch(error){hideLoader(),console.log(error)}},$scope.delete=async function({idSubFamilia:idSubFamilia}){try{let{isConfirmed:isConfirmed}=await Swal.fire({icon:"warning",html:"<small>Esta seguro/a de eliminar esta subfamilia ahora?</small>",showCinfirmButton:!0,confirmButtonText:"Si, eliminar",showCancelButton:!0,cancelButtonText:"No, cancelar",allowOutsideClick:!1});isConfirmed&&(showLoader(),subFamiliaSvc.delete(idSubFamilia).then(response=>{hideLoader(),"0"!=response.code?"1"==response.code&&(tS.toastr("success",response.message,response.titleSms),$scope.getSubFamilias()):tS.toastr("warning",response.message,response.titleSms)}).catch(error=>{hideLoader(),console.log(error)}))}catch(error){hideLoader(),console.log(error)}}}app.controller("subFamiliaCtrl",subFamiliaCtrl),subFamiliaCtrl.$inject=["$scope","subFamiliaService","commonService","toastService"]}(window.angular);